namespace A33.Instrument.Protocol;
public static class ModbusRequestCodec { public static byte[] ReadHolding(ushort unit,ushort address,ushort count){return new[]{(byte)unit,(byte)3,(byte)(address>>8),(byte)address,(byte)(count>>8),(byte)count};} public static byte[] WriteSingle(ushort unit,ushort address,ushort value){return new[]{(byte)unit,(byte)6,(byte)(address>>8),(byte)address,(byte)(value>>8),(byte)value};} public static byte[] WriteMultiple(ushort unit,ushort address,ReadOnlySpan<ushort> values){if(values.Length==0||values.Length>123)throw new ArgumentOutOfRangeException(nameof(values));var p=new byte[7+values.Length*2];p[0]=(byte)unit;p[1]=16;p[2]=(byte)(address>>8);p[3]=(byte)address;p[4]=(byte)(values.Length>>8);p[5]=(byte)values.Length;p[6]=(byte)(values.Length*2);for(var i=0;i<values.Length;i++){p[7+2*i]=(byte)(values[i]>>8);p[8+2*i]=(byte)values[i];}return p;} }
